liveField=function(m){if(mode==='2D'||failed)return oldLiveField(m);return `<div class="stadium-toolbar"><span class="tag green">3D MATCH ENGINE</span><label>Camera <select aria-label="3D camera" onchange="setStadiumCamera(this.value)">${['Broadcast','End zone','Player cam','Tactical','Orbit'].map(n=>`<option ${cameraMode===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="small secondary" onclick="resetStadiumCamera()">Reset camera</button><button class="small secondary" onclick="replay3D()" ${!m.replay||animating?'disabled':''}>↺ Replay</button><button class="small secondary" onclick="window.matchAudio.toggle()">${window.matchAudio.on?'♫ Sound on':'♫ Enable sound'}</button><label class="audio-volume">Volume <input aria-label="Game audio volume" type="range" min="0" max="1" step="0.05" value="${window.matchAudio.volume}" oninput="window.matchAudio.setVolume(this.value)"></label><button class="link" onclick="toggleStadiumView()">2D view</button></div><div class="motion-preview"><span>Animation preview · no match impact</span>${['Throw','Run','Juke','Dive'].map(n=>`<button onclick="previewHumanMove('${n}')" ${animating?'disabled':''}>${n}</button>`).join('')}</div><div class="stadium-wrap"><div id="stadium-host" class="stadium-host"></div><div class="stadium-bug">${replaying?'REPLAY':'LIVE'} <span>●</span> ${clubs[m.a][0]} vs ${clubs[m.b][0]}</div><div class="stadium-caption">${esc(m.last?.text||'Set your formation. The sideline is yours.')}</div><div class="play-transport"><span id="play-phase">${stadium?.phaseText||'READY'}</span><button onclick="pauseStadiumPlay()" ${!animating?'disabled':''}>${stadium?.action?.paused?'▶ Resume':'Ⅱ Pause animation'}</button><label>Playback <select aria-label="Animation playback speed" onchange="setStadiumRate(this.value)">${[.5,1,1.5].map(r=>`<option value="${r}" ${(stadium?.playbackRate||1)===r?'selected':''}>${r}×</option>`).join('')}</select></label><input id="play-timeline" type="range" min="0" max="100" value="${stadium?.action?stadium.action.elapsed/stadium.action.duration*100:stadium?.heldKey?100:0}" ${!animating?'disabled':''} oninput="seekStadiumPlay(this.value)" aria-label="Play animation progress"></div><div class="stadium-hint">Drag to orbit · Scroll to zoom</div></div>`};
window.setStadiumCamera=function(v){cameraMode=v;save()};window.toggleStadiumView=function(){if(animating)return;mode=mode==='3D'?'2D':'3D';render()};
render=function(){oldRender();window.matchAudio.sync();let host=document.getElementById('stadium-host');if(host&&state.live){try{if(!stadium)stadium=new Stadium(host);else stadium.attach(host);if(!animating&&stadium.heldKey!==matchVisualKey(state.live))stadium.setup(state.live)}catch(e){failed=true;mode='2D';console.warn('3D initialization failed',e);oldRender();toast('3D is unavailable on this device. The 2D match view is still playable.')}}else{stadium?.stop();if(view==='Matchday'&&state.live&&(mode==='2D'||failed)){let field=document.getElementById('live-pitch');if(field&&!failed)field.insertAdjacentHTML('beforebegin','<div class="stadium-toolbar"><button class="small secondary" onclick="toggleStadiumView()">Switch to 3D →</button></div>')}}let legend=document.querySelector('.match-controls')?.nextElementSibling;if(legend&&mode==='3D'&&!failed)legend.textContent='Colored jerseys: offense · White jerseys: defense | Blue: scrimmage | Yellow: first down';let note=document.querySelector('#app > .subtitle');if(view==='Matchday'&&state.live&&note)note.textContent='Personnel, coverage and execution shape each play. Replay controls do not change the result. Simplified officiating and overtime rules apply.'};
function duration3D(){return autoSpeed===750?6000:autoSpeed===2500?11000:8500}
function finishPlayback(){animating=false;replaying=false;if(view==='Matchday')render()}
window.pauseStadiumPlay=function(){if(!stadium?.action)return;stadium.action.paused=!stadium.action.paused;let button=document.querySelector('.play-transport button');if(button)button.textContent=stadium.action.paused?'▶ Resume':'Ⅱ Pause animation'};
window.seekStadiumPlay=function(v){if(!stadium?.action)return;stadium.action.paused=true;stadium.action.elapsed=Math.min(.999,Number(v)/100)*stadium.action.duration;stadium.updateAction(0);let b=document.querySelector('.play-transport button');if(b)b.textContent='▶ Resume'};
window.setStadiumRate=function(v){if(stadium)stadium.playbackRate=Number(v)};
window.resetStadiumCamera=function(){cameraMode='Broadcast';if(stadium){stadium.orbit={angle:1.05,height:30,radius:42};stadium.camera.position.set(stadium.focus.x+8,19,stadium.focus.z+31);stadium.target.copy(stadium.focus)}render()};
snap=function(){if(mode==='2D'||failed)return oldSnap();let m=state.live;if(!m||m.finished||m.halftime||animating)return;replaying=false;let before=JSON.parse(JSON.stringify(m));delete before.replay;animating=true;render();seed=(Date.now()^(m.plays*7919))>>>0;let last=resolveSnap();let after=JSON.parse(JSON.stringify(state.live));delete after.replay;state.live.replay={before,after,last:JSON.parse(JSON.stringify(last))};save();let duration=duration3D();if(stadium){stadium.play(before,after,last,duration,finishPlayback);window.matchAudio.tone(180,.14,.055,'triangle')}else finishPlayback()};
window.replay3D=function(){let data=state.live?.replay;if(!data||animating||mode!=='3D'||failed)return;pauseAuto();animating=true;replaying=true;render();stadium?.play(data.before,data.after,data.last,10000,finishPlayback)};
window.previewHumanMove=function(name){if(animating||!state.live||mode!=='3D'||failed)return;pauseAuto();let before=JSON.parse(JSON.stringify(state.live));delete before.replay;before.poss=teamIndex(before);before.spot=45;before.offense='Shotgun spread';before.official=null;let after=JSON.parse(JSON.stringify(before));after.spot=61;let last={start:45,spot:61,poss:before.poss,passing:name==='Throw',call:name==='Throw'?'Deep pass':name==='Juke'?'Outside run':'Inside run',animation:name.toLowerCase(),text:'ANIMATION PREVIEW — '+name+' · no match impact'};if(name==='Run')last.spot=54;animating=true;replaying=true;cameraMode='Player cam';render();stadium?.play(before,after,last,10000,()=>{stadium.heldKey=matchVisualKey(state.live);finishPlayback()});let caption=document.querySelector('.stadium-caption');if(caption)caption.textContent=last.text};
const stadiumGo=go;go=function(v){if(v!=='Matchday')window.broadcast?.stop();if(v!=='Matchday'&&stadium?.action){stadium.action.onComplete=()=>{animating=false;replaying=false};stadium.finishSequence()}stadiumGo(v)};
const stadiumStartCareer=startCareer;startCareer=function(i){if(stadium){stadium.action=null;stadium.heldKey=null}stadiumStartCareer(i)};

render();
import('./franchise/ui.mjs').catch(error=>{console.error('Franchise modules failed',error);toast('Franchise modules could not load. Existing matchday remains available.')});

window.finishMatchPlayback=function(){pauseAuto();window.broadcast?.stop();if(stadium?.action)stadium.finishSequence();if(animationTimer){clearTimeout(animationTimer);animationTimer=null}animating=false;replaying=false;};
